import sys

def get_file_counts(filename):
    """Counts lines, words, and characters in a file.
    Returns (lines, words, characters) or None if file not found.
    """
    try:
        with open(filename, 'r') as f:
            content = f.read()
            # Line count is newline characters
            lines = content.count('\n')
            # Word count is whitespace-separated words
            words = len(content.split())
            # Character count is total characters
            chars = len(content)
            return lines, words, chars
    except FileNotFoundError:
        return None

def run_wc(filenames):
    """The core logic of wc. Given a list of filenames, 
    it prints the counts and optional total.
    """
    if not filenames:
        return

    all_counts = []
    for filename in filenames:
        counts = get_file_counts(filename)
        if counts is None:
            return f"Error: {filename} not found", 1
        all_counts.append((counts, filename))

    for (lines, words, chars), filename in all_counts:
        if len(filenames) > 1:
            print(f"{lines:<7} {words:<7} {chars:<7} {filename}")
        else:
            print(f"{lines:<7} {words:<7} {chars:<7}")

    if len(filenames) > 1:
        total_lines = sum(c[0] for c, f in all_counts)
        total_words = sum(c[1] for c, f in all_counts)
        total_chars = sum(c[2] for c, f in all_counts)
        print(f"{total_lines:<7} {total_words:<7} {total_chars:<7} total")

    return None, 0

def main():
    filenames = sys.argv[1:]
    if not filenames:
        return

    error_msg, exit_code = run_wc(filenames)
    if error_msg:
        print(error_msg, file=sys.stderr)
        sys.exit(exit_code)

if __name__ == "__main__":
    main()

